"use strict";
const P = new p5.Shader(this._renderer,
    // vert
    `attribute vec3 aPosition;
varying vec2 vuv;

void main()
{
		const float scale = .5;
    gl_Position = vec4(aPosition.x * .5, aPosition.y, 0, scale);

		vuv = aPosition.xy;

}`, // frag
		`precision highp float;
varying vec2 vuv;
uniform float time;

void main()
{
    // frame
    if (abs(vuv.x) > .485 || abs(vuv.y) > .485) 
		{
        gl_FragColor = vec4(0.5, 0.5, 0.5, 1.);
        return;
    }
		// position
		vec2 p = vuv;

    // lights
    float l = 0.; 

		// for more or less understandable reasons a loop must be phrased this way  
    ${"for(float _ii = 0.1; _ii<0.25; _ii+=.01 )"}
		l += .005 / length( p + 
								 vec2(cos(10. * _ii * time) * _ii, -sin(10. * _ii * time) * _ii) // rotation
								); 

    // shade 
    gl_FragColor.rgb = vec3(l, l, l + .1);
    gl_FragColor.a = 1.;

}`);

var osc, osc2;
function setup() 
{
    createCanvas(windowWidth, windowHeight, WEBGL);

    noStroke();

    setAttributes({
        alpha: !1,
        depth: !1,
        stencil: !1,
        antialias: !1,
        premultipliedAlpha: !1,
        presereDrawingBuffer: !1,
        failIfMajorPerformanceCaveat: !1
    });

    background(255);
    shader(P);

	  osc = new p5.Oscillator(0, 'sine');
    osc.start();

    osc2 = new p5.Oscillator(0, 'sine');
    osc2.start();

}

function draw() 
{

		let tFreq = PI++ * .0051 * 200;
		let tPan = PI++ * .1;

    osc.pan(sin(tPan), .1)
    osc.freq(160.0 + ceil(-3.0 * (sin(tFreq))));

    osc2.pan(sin(tPan), .1)
    osc2.freq(100.0 + ceil(-3.0 * (sin(tFreq))));


    P.setUniform("time", millis() * .001);

    plane(0, 0);
}

function windowResized() 
{
    resizeCanvas(windowWidth, windowHeight);
}

